const GOVX_L = (x, en) => (Array.isArray(x) ? x[en ? 1 : 0] : x || "");
function GovSrc({ src, en }) {
  if (!src || !src.length) return null;
  src = src.filter((x, i, a) => a.findIndex((y) => y.url === x.url && y.name === x.name) === i);
  return (
    <div style={{ fontSize: 10.5, color: C.dim, marginTop: 6, lineHeight: 1.6 }}>
      {en ? "Sources: " : "出典："}
      {src.map((x, i) => <span key={i}>{i ? " ／ " : ""}<a href={x.url} target="_blank" rel="noopener noreferrer" style={{ color: C.dim }}>{x.name}</a>{x.kind === "二次" ? (en ? " (secondary)" : "（二次）") : ""}</span>)}
    </div>
  );
}
function GovPills({ items, val, onPick, col = C.teal }) {
  return (
    <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
      {items.map(([k, label]) => (
        <button key={k} onClick={() => onPick(k)} style={{ background: val === k ? col : C.surface, color: val === k ? C.bg : C.text, border: `1px solid ${val === k ? col : C.line}`, borderRadius: 999, padding: "4px 11px", fontSize: 11.5, fontWeight: 700, cursor: "pointer" }}>{label}</button>
      ))}
    </div>
  );
}
