          const mx = heads.map((_, j) => Math.max(1, ...ov.map((o) => o.n[j])));
          const ri = (n, j) => (n === 0 ? -1 : Math.min(GV_RAMP.length - 1, Math.floor((n / mx[j]) * GV_RAMP.length - 1e-9)));
