      {mode === "usecase" && <GovUseCase en={en} go={go} onIncident={openIncident} onTab={onTab} deep={deep && deep.mode === "usecase" ? deep.q : null} />}
      {mode === "quiz" && <GovQuiz en={en} preset={navOf("quiz") ? navOf("quiz").preset : null} />}
